export interface AuditCliRun { code: number | null; stdout: string; stderr: string; leftovers: string[] }

/**
 * Runs `nexus audit <args>` (see `cliEntry`) with a throwaway HOME, its own temp directory and no operator
 * environment but `env`. `leftovers`: what the command left in that temp directory (the export's private copy would be one).
 */
export function runAudit(args: string[], env: Record<string, string> = {}): Promise<AuditCliRun> {
  const base = { ...process.env };
  for (const key of Object.keys(base)) if (/^(LOCAL_LLM_|LOCAL_HARNESS_|NEXUS_|GIT_)/.test(key) || key === "NODE_TEST_CONTEXT" || key === "FORCE_COLOR" || key === "NO_COLOR") delete base[key];
  const home = env.HOME ?? makeHome();
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-audit-test-tmp-"));
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [...cliEntry(), "audit", ...args], {
      cwd: CLI_DIR,
      env: { ...base, HOME: home, TMPDIR: tmp, NO_COLOR: "1", XDG_CONFIG_HOME: path.join(home, ".config"), XDG_DATA_HOME: path.join(home, ".local", "share"), XDG_STATE_HOME: path.join(home, ".local", "state"), XDG_CACHE_HOME: path.join(home, ".cache"), ...env },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout!.on("data", (chunk) => (stdout += chunk));
    },
    authSeen,
    close,
  };
}

/** Temporary git repository with one committed file. */
export function makeRepo(files: Record<string, string> = {}): string {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-sidecar-"));
  fs.writeFileSync(path.join(repo, "base.txt"), "base\n");
  for (const [name, content] of Object.entries(files)) {
    const full = path.join(repo, name);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content);
  }
  execSync("git init -q && git config user.name t && git config user.email t@t.invalid && git add . && git commit -qm base", { cwd: repo, stdio: "ignore" });
  return repo;
}

export function makeHome(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), "nexus-home-"));
}

/** Seed an isolated HOME with explicit trust for a PTY test that needs to reach the REPL. */
export function trustWorkspace(home: string, workspace: string): void {
  const trustDir = path.join(home, ".config", "nexus");
  fs.mkdirSync(trustDir, { recursive: true, mode: 0o700 });
  fs.writeFileSync(
    path.join(trustDir, "trusted_workspaces.json"),
    JSON.stringify({ trustedPaths: [fs.realpathSync(workspace)] }, null, 2),
    { mode: 0o600 },
  );
}

export async function waitUntil(cond: () => boolean, timeoutMs = 10000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!cond()) {
    if (Date.now() > deadline) throw new Error("timed out");
    await new Promise((r) => setTimeout(r, 10));
  }
}

/**
 * True once `pid` has terminated. A zombie counts as terminated: under a PID 1 that does not reap (some containers), a
 * killed process stays a zombie, and `kill(pid, 0)` still succeeds on it.
 */
export function processGone(pid: number): boolean {
  try {
    process.kill(pid, 0);
  } catch (error: unknown) {
    return (error as NodeJS.ErrnoException)?.code === "ESRCH";
  }
  // The process exists or is a zombie. `ps -p` exits 1 with no output once the pid is gone; if ps cannot run, the
  // process is not proven gone.
  const ps = spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" });
  if (ps.error || (ps.status !== 0 && ps.status !== 1)) return false;
  const stat = ps.stdout.trim();
  return stat === "" || stat.startsWith("Z");
}

