      receipt_id: receiptId,
      receipt_sha256: createHash("sha256").update(JSON.stringify(result), "utf8").digest("hex"),
      issued_at: issuedAt,
      surface: this.config.surface,
      session_id: binding.sessionId ?? null,
      workspace,
      base_pinned_at: binding.base.at,
      result,
    });
